param([string]$DockerRoot="C:\dev\Docker",[switch]$IncludeIbmMq)
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest
$names=@("cpf-rabbitmq","cpf-artemis","cpf-tcp-simulator","cpf-mailpit","cpf-wiremock","cpf-toxiproxy","cpf-otel-collector");if($IncludeIbmMq -or ((docker ps -a --format "{{.Names}}") -contains "cpf-ibm-mq")){$names+="cpf-ibm-mq"};$running=@(docker ps --format "{{.Names}}"|Where-Object{$_ -in $names});if($running.Count -gt 0){& docker stop @running;if($LASTEXITCODE -ne 0){throw "QA39 Runtime 중지 실패(exit=$LASTEXITCODE)"}};foreach($name in $names){docker container inspect $name *> $null;if($LASTEXITCODE -eq 0){docker update --restart=no $name *> $null;if($LASTEXITCODE -ne 0){throw "Restart Policy 설정 실패: $name"}}};$still=@(docker ps --format "{{.Names}}"|Where-Object{$_ -in $names});if($still.Count -gt 0){throw "중지되지 않은 Container: $($still -join ', ')"};Write-Host "CPF QA39 Runtime 중지 완료 / Restart Policy no" -ForegroundColor Green
